item.aggregated_output:
{
  "103:1": "وَٱلْعَصْرِ",
  "103:2": "إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ",
  "103:3": "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ"
}

{"connection_id": "BC-b87f8d74dfbbfdba8a59", "ref": "1 Clement 13:1", "target": "sec14", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Christian reception of Jeremiah's anti-boasting formula", "note": "Clement applies Jeremiah's warning against boasting in wisdom, strength, and wealth to Christian humility, giving an early Christian interpretation of the status critique in Jeremiah 9."}
{"connection_id": "BC-0c37eca6542458774c22", "ref": "Didache 4:3", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "impartial correction and just judgment", "note": "The church rule commands just judgment and no partiality when correcting transgressions; it gives the commentary's move from rank to religious conduct a concrete communal practice."}
{"connection_id": "BC-b27511f6b893fe2a8a09", "ref": "SBLGNT:1Cor.1.26", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "noble birth among the called", "note": "The commentary contrasts lineage and rank with the surah's criterion of faith and deeds; Paul reminds the Corinthians that few were wise, powerful, or well-born when called, showing the community was not selected by elite status."}
{"connection_id": "BC-2bb8a14055a6e5a215ec", "ref": "SBLGNT:1Cor.1.26", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "few of noble birth among the called", "note": "Paul says the called include few people of noble birth; this directly tests the commentary's noble lineage against the community formed by faith."}
{"connection_id": "BC-03c6a783e0861ee1ad58", "ref": "SBLGNT:1Cor.1.27", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "God chooses the weak", "note": "The note includes the lowest ranks within humanity; Paul says God chose the world's weak and foolish to shame the strong and wise, reversing the social measure of worth."}
{"connection_id": "BC-63e088af573bbe78dbdf", "ref": "SBLGNT:1Cor.1.27", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "God chooses the weak", "note": "Paul says God chooses what the world calls weak; the commentary's hanâsir are weak people, yet weakness does not determine their worth before God."}
{"connection_id": "BC-5ab579ec2db28254f7a8", "ref": "SBLGNT:1Cor.1.28", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "lowly and despised chosen", "note": "The commentary highlights the lowliest freedmen and weak people; Paul says God chose what is low and despised, even what is not, to nullify what is, directly reversing status."}
{"connection_id": "BC-4ea1f498c1b6ca704fc0", "ref": "SBLGNT:1Cor.1.28", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "God chooses the low and despised", "note": "Paul's low and despised are chosen to overturn what claims standing; this closely matches the commentary's lowest freedmen and its reversal of rank."}
{"connection_id": "BC-2c381a5c3dba33b9b66b", "ref": "SBLGNT:1Cor.1.29", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "no human may boast before God", "note": "The commentary removes lineage as a basis for superiority; Paul says God's choice leaves no human able to boast before God, explicitly closing off inherited or social prestige."}
{"connection_id": "BC-3cf252e9ae6519e9d89f", "ref": "SBLGNT:1Cor.1.29", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "no flesh may boast before God", "note": "Paul gives the aim of the preceding choice of low people: no human may boast before God; inherited rank cannot ground superiority."}
{"connection_id": "BC-986166b1df896c5b88c7", "ref": "SBLGNT:1Cor.12.22", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "weaker parts are indispensable", "note": "The commentary notes that low and weak people remain within the human category; Paul says body parts that seem weaker are indispensable, giving low status a necessary role in the community."}
{"connection_id": "BC-330fe8478ab9cc2733ea", "ref": "SBLGNT:1Cor.12.23", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "less honorable parts receive greater honor", "note": "Paul says the body's less honorable parts are treated with greater honor; this is a concrete reversal of rank within the community, not merely a claim that all parts exist."}
{"connection_id": "BC-64cae834ffbac2b08f68", "ref": "SBLGNT:1Cor.15.22", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "all die in Adam, life in Christ", "note": "The commentary says khusr encompasses humanity without regard to rank; Paul says all die in Adam and all are made alive in Christ, placing humanity under shared death and framing life through Christ."}
{"connection_id": "BC-3ad2b0a94ca84f6fabbd", "ref": "SBLGNT:1Cor.15.22", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "all die in Adam, made alive in Christ", "note": "Paul places death on all through Adam and life in Christ; one human lineage shares loss while a new relation changes the outcome."}
{"connection_id": "BC-7f03602855949f78961d", "ref": "SBLGNT:1Cor.7.22", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "called slave is Lord's freedperson", "note": "Paul calls the slave summoned by the Lord a freedperson of the Lord; the commentary's pairing of freed status with the lowest rank meets a spiritual reversal."}
{"connection_id": "BC-2dda3ba215060cda5f40", "ref": "SBLGNT:1Pet.1.17", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "impartial judgment of each person's work", "note": "The commentary says lineage does not decide who is lost and deeds mark the distinction; Peter describes the Father as judging each person's work impartially, closely joining both claims."}
{"connection_id": "BC-67f0ea43e30cc5b2effc", "ref": "SBLGNT:1Pet.1.17", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "Father judges each one's work impartially", "note": "The letter calls God an impartial judge of each person's work; filial language cannot turn family standing into exemption."}
{"connection_id": "BC-d29af778bfafd14d1f07", "ref": "SBLGNT:1Pet.1.18", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "inherited way named futile", "note": "Readers are said to have been redeemed from a futile way of life handed down by their ancestors; inheritance itself can transmit what must be left behind."}
{"connection_id": "BC-b813234023aa9d2624c4", "ref": "SBLGNT:1Pet.2.10", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "once no people, now God's people", "note": "The letter says its recipients once lacked peoplehood but now are God's people; belonging is conferred beyond inherited status."}
{"connection_id": "BC-914ae4f41dc8f10f0210", "ref": "SBLGNT:1Tim.6.17", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rich told not to be haughty", "note": "The rich are told not to set hope on uncertain riches but on God; high material standing offers no sure standing before him."}
{"connection_id": "BC-7b00a21bc68de27a0f0b", "ref": "SBLGNT:1Tim.6.18", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rich commanded to be rich in works", "note": "The wealthy are instructed to do good and be rich in good works; ethical action replaces possessions as the relevant kind of wealth."}
{"connection_id": "BC-6e5fe65e757550bb14c7", "ref": "SBLGNT:2Pet.2.5", "target": "sec14", "tradition": "incil", "kind": "paralel", "basis": "Noah preserved, ungodly world judged", "note": "The epistle calls Noah a herald of righteousness and says God preserved him while bringing the flood on the ungodly; it places righteousness at the center of the Noah story."}
{"connection_id": "BC-dc16600963e2e47b0bbb", "ref": "SBLGNT:Acts.10.34", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "God shows no partiality", "note": "The commentary includes high and low in the same human category; after Peter's vision opens the message to Gentiles, he says God shows no partiality, removing inherited peoplehood as a barrier."}
{"connection_id": "BC-04e1bbe8282b56d85e0c", "ref": "SBLGNT:Acts.10.35", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "fear of God and right action across nations", "note": "The commentary makes faith and deeds the dividing criterion; Peter says a person from any nation who fears God and does what is right is acceptable, explicitly replacing ancestry with religious conduct."}
{"connection_id": "BC-2acfb8efd4e3f13e6c45", "ref": "SBLGNT:Acts.10.35", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "fear God and do right in every nation", "note": "Peter says people in every nation who fear God and do right are acceptable; action and reverence replace descent as a measure of worth."}
{"connection_id": "BC-d358c4d9ffac5b3bbdb3", "ref": "SBLGNT:Acts.17.26", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "all nations from one ancestor", "note": "The commentary pairs lineage with the universal human category; Paul says God made every nation from one ancestor and appointed their times and boundaries, giving common human origin a concrete biblical formulation."}
{"connection_id": "BC-4007dad24c130ae28c1a", "ref": "SBLGNT:Acts.17.26", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "all nations from one ancestor", "note": "Paul says God made every nation from one source; the commentary's insan covers noble and lowly despite claims based on descent."}
{"connection_id": "BC-3015cbacd78d5a3ce562", "ref": "SBLGNT:Acts.17.27", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "all peoples directed to seek God", "note": "Paul continues that the nations' situation is ordered so they might seek God; this adds a shared religious task to the common ancestry in the preceding verse."}
{"connection_id": "BC-845c4575182923459217", "ref": "SBLGNT:Acts.4.13", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "ordinary followers recognized with Jesus", "note": "The commentary says Noah's elite opponents treat low status as grounds to reject his message; authorities see Peter and John as uneducated and ordinary yet recognize their association with Jesus, a counterexample to status-based dismissal."}
{"connection_id": "BC-62225fcfda03bbf35f95", "ref": "SBLGNT:Acts.4.13", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "ordinary followers before rulers", "note": "Council members see Peter and John as uneducated ordinary men yet recognize their boldness and connection with Jesus; low standing does not discredit their witness."}
{"connection_id": "BC-f88cd5af1e950b5c1af9", "ref": "SBLGNT:Col.3.11", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "barbarian and slave categories dissolved", "note": "Paul names Greek, Jew, barbarian, Scythian, slave, and free, then makes Christ central to all; despised ethnic and servile labels cannot set rank in this community."}
{"connection_id": "BC-e172f274e6fcb7be8f0b", "ref": "SBLGNT:Eph.2.10", "target": "sec14", "tradition": "incil", "kind": "karsi_anlati", "basis": "good works as the result of grace", "note": "The preceding verses deny that works earn salvation, but Ephesians says believers are created in Christ for good works; this preserves a role for deeds while locating them as the result, not the basis, of salvation."}
{"connection_id": "BC-a2a2f3a15db082cda24e", "ref": "SBLGNT:Eph.2.10", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "created for good works", "note": "Believers are described as created in Christ for good works; the commentary's exception likewise joins faith to enacted righteousness."}
{"connection_id": "BC-7e9955a569c7a927c8f8", "ref": "SBLGNT:Eph.2.8", "target": "sec14", "tradition": "incil", "kind": "karsi_anlati", "basis": "salvation as gift through faith", "note": "The commentary says the final distinction is by faith and deeds; Ephesians says salvation comes by grace through faith as God's gift, locating its source in grace and faith rather than human achievement."}
{"connection_id": "BC-f988b538bb916b399015", "ref": "SBLGNT:Eph.2.9", "target": "sec14", "tradition": "incil", "kind": "karsi_anlati", "basis": "works are not the basis for boasting", "note": "Ephesians says salvation is not from works so that no one may boast, a specific difference from the commentary's formulation that righteous deeds help distinguish the saved."}
{"connection_id": "BC-6db08609a8d29c09c437", "ref": "SBLGNT:Eph.6.9", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "master and slave share impartial judge", "note": "Masters are told to abandon threats because their Master in heaven shows no favoritism; the hierarchy over dependent people is judged by one standard."}
{"connection_id": "BC-7bc2fe7ceb80f796ad3d", "ref": "SBLGNT:Gal.3.28", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "Jew/Greek and slave/free made one", "note": "The commentary says al-insan includes noble and low alike; Paul names Jew/Greek and slave/free distinctions and says they do not divide those in Christ, shifting standing away from inherited and social categories."}
{"connection_id": "BC-5fc51942b6bbbfb31365", "ref": "SBLGNT:Gal.3.28", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "slave and free one in Christ", "note": "Paul says slave and free share one standing in Christ; the commentary's very low freedmen cannot be excluded by their former rank."}
{"connection_id": "BC-7f14a75c2c540f507312", "ref": "SBLGNT:Gal.3.7", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "faith makes Abraham's children", "note": "Paul calls those of faith Abraham's children; the relationship to an ancestor is redefined by faith rather than birth."}
{"connection_id": "BC-02c38e95550c6e117a91", "ref": "SBLGNT:Heb.11.7", "target": "sec14", "tradition": "incil", "kind": "paralel", "basis": "Noah's faith condemns the world", "note": "Hebrews says Noah responded in faith to warning, built the ark, and condemned the world; the Noah scene is evaluated by faith rather than the status of his critics."}
{"connection_id": "BC-1ea19397aad3d8f91d63", "ref": "SBLGNT:Heb.7.16", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "priesthood beyond fleshly descent", "note": "The new priest's standing is described as arising from indestructible life rather than a law of bodily descent; a religious rank is detached from genealogy."}
{"connection_id": "BC-9a2ecb7caa5608e29c72", "ref": "SBLGNT:Jas.1.10", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rich person in humiliation", "note": "James tells the rich person to boast in humiliation because wealth fades; high worldly rank cannot protect a person from loss."}
{"connection_id": "BC-e5786c75cd5d5dab68f6", "ref": "SBLGNT:Jas.1.9", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "lowly believer boasts in exaltation", "note": "James tells the lowly brother to boast in exaltation; faith gives a rank opposite to his social place."}
{"connection_id": "BC-b9afb81d9db3d6985d77", "ref": "SBLGNT:Jas.2.17", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "faith without works is dead", "note": "James calls faith dead when it lacks works; the surah commentary expressly says its exception requires both belief and action."}
{"connection_id": "BC-d48408933e54c3ea9955", "ref": "SBLGNT:Jas.2.2", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rings and clothing mark social rank", "note": "The commentary names noble descent and the lowest freedmen; James's assembly scene distinguishes a gold-ringed, finely dressed visitor from a poor person in shabby clothes, making rank's visible signs concrete."}
{"connection_id": "BC-8568b0add906e33aa9d7", "ref": "SBLGNT:Jas.2.3", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "preferential seating for the rich", "note": "The note says status should not decide human worth; James depicts the rich being offered a good seat while the poor are made to stand or sit below, then condemns the community's class judgment."}
{"connection_id": "BC-38b094704c0a57bb1e95", "ref": "SBLGNT:Jas.2.3", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "honored and low seats", "note": "A richly dressed visitor receives a good seat while a poor visitor is told to stand or sit below; the congregation enacts exactly the rank division questioned in the commentary."}
{"connection_id": "BC-3dba7e4d51847e14d5d1", "ref": "SBLGNT:Jas.2.5", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "poor rich in faith and heirs", "note": "The commentary says the later ayah distinguishes by faith and work; James says God chose the poor to be rich in faith and heirs of the kingdom, reversing social rank through faith."}
{"connection_id": "BC-aabd08a702915ce9d7c3", "ref": "SBLGNT:Jas.2.5", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "poor chosen, rich in faith", "note": "James says God chose the poor in the world to be rich in faith and heirs of the kingdom; faith overturns the low social rank assigned to the weak."}
{"connection_id": "BC-b88c55037bfedd67a0e7", "ref": "SBLGNT:Jas.2.6", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "poor dishonored, rich oppress", "note": "James reproaches believers for dishonoring the poor while the rich oppress them; this supplies the social action behind calling the lowly inferior."}
{"connection_id": "BC-d8ece7171172c601c1f0", "ref": "SBLGNT:Jas.2.9", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "partiality is sin", "note": "The commentary replaces inherited rank with a religious-ethical criterion; James explicitly calls favoritism toward status groups sin, giving the social hierarchy a moral verdict."}
{"connection_id": "BC-899356720b21f4369914", "ref": "SBLGNT:John.1.12", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "believers become children of God", "note": "The commentary says lineage does not decide who belongs among the saved; John says those who receive and believe in Jesus' name are given the status of God's children."}
{"connection_id": "BC-0c4e56489a76f8b528c6", "ref": "SBLGNT:John.1.12", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "believers receive child status", "note": "Those who receive the Word and believe are given the right to become God's children; faith supplies belonging beyond inherited family standing."}
{"connection_id": "BC-08e96b35b9b875437200", "ref": "SBLGNT:John.1.13", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "birth not from blood but from God", "note": "John specifies that God's children are not born from blood or human will but from God, directly denying natural descent as the source of religious standing."}
{"connection_id": "BC-379516d06bbf4196ae5d", "ref": "SBLGNT:John.1.13", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "birth not from bloodlines", "note": "The new children of God are born neither from blood nor human will but from God; the verse explicitly displaces pedigree as decisive status."}

{"connection_id": "BC-bca35c3510d66b7489cf", "ref": "SBLGNT:John.7.48", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rulers use their unbelief as test", "note": "The authorities ask whether any ruler or Pharisee has believed in Jesus; they make elite standing a test of truth, like the elite objection to Noah's lowly followers."}
{"connection_id": "BC-c2a7ece410db0c9ae675", "ref": "SBLGNT:John.7.49", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "elite contempt for the crowd", "note": "The commentary's Noah narrative has elites call his followers the lowest; Pharisees dismiss the crowd as ignorant of the law and accursed, a close instance of status-bearing leaders discrediting ordinary people."}
{"connection_id": "BC-2b785d6a204c4e05c87a", "ref": "SBLGNT:John.7.49", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "crowd dismissed as ignorant and cursed", "note": "The authorities call the believing crowd ignorant of the law and cursed; this closely matches discrediting a message by degrading its low status adherents."}
{"connection_id": "BC-a8d1f71a8c415d9fe9be", "ref": "SBLGNT:John.8.39", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "Abraham's children must do Abraham's works", "note": "The commentary says rank by descent gives way to faith and action; Jesus answers a claim of Abrahamic descent by making Abraham-like deeds the test of true kinship."}
{"connection_id": "BC-2c0a22420ee364afa96b", "ref": "SBLGNT:John.8.39", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "Abraham's children do Abraham's works", "note": "Jesus tells those claiming Abraham as father that true children would do Abraham's deeds; a claimed ancestor must be matched by conduct."}
{"connection_id": "BC-2321505e7e4ffb723d65", "ref": "SBLGNT:John.9.34", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "healed man dismissed as unfit to teach", "note": "The authorities tell the formerly blind man he was born entirely in sin and expel him when he challenges them; presumed low status overrides the truth of his testimony."}
{"connection_id": "BC-76e90ba48f8b047fbaaf", "ref": "SBLGNT:Luke.1.52", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rulers brought down, humble exalted", "note": "The commentary sets lineage and high/low rank beside universal human loss; Mary's praise says God brings rulers from thrones and exalts the lowly, a direct reversal of social rank."}
{"connection_id": "BC-e7f8e4afda5aac72b3b5", "ref": "SBLGNT:Luke.1.52", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rulers lowered, humble raised", "note": "Mary's song says God brings rulers down from thrones and lifts the humble; the commentary likewise sets divine standing against human rank."}
{"connection_id": "BC-9f20c5057bb36df0d269", "ref": "SBLGNT:Luke.1.53", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "hungry filled, rich sent empty", "note": "The hungry receive good things while the rich leave empty; this gives material force to the commentary's pairing of the weak and low with a reversal of value."}
{"connection_id": "BC-c48766d1229565afb0f8", "ref": "SBLGNT:Luke.12.20", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rich man's death defeats his security", "note": "The commentary pairs rank with human loss; God tells the rich landowner his life is required that night, so accumulated wealth and status cannot secure him from death."}
{"connection_id": "BC-cac027e93258bc5f1a8b", "ref": "SBLGNT:Luke.12.21", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rich toward God", "note": "The commentary says the final distinction is not lineage but faith and deeds; Jesus applies the rich fool's story to one who stores treasure for himself but is not rich toward God."}
{"connection_id": "BC-7ecd65b0fbc719ece59a", "ref": "SBLGNT:Luke.15.2", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "elites complain of receiving sinners", "note": "Pharisees and scribes grumble that Jesus welcomes sinners and eats with them; association with despised people becomes their reason to reject him."}
{"connection_id": "BC-04ab16f2f5bb756e0439", "ref": "SBLGNT:Luke.16.22", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "both die; poor man exalted", "note": "The commentary includes the high and low in humanity's loss; Luke has both Lazarus and the rich man die, but Lazarus is carried to Abraham's side while the rich man is buried, reversing earthly rank."}
{"connection_id": "BC-edd8e0942cdf2cb1c61d", "ref": "SBLGNT:Luke.16.22", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "poor Lazarus received after death", "note": "Lazarus, poor at the rich man's gate, is carried to Abraham's side while the rich man dies; low standing in life is reversed at death."}
{"connection_id": "BC-0e357886e99857350c72", "ref": "SBLGNT:Luke.16.25", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "life's status reversed after death", "note": "The note says rank cannot determine the final distinction; Abraham tells the rich man that he received good things in life while Lazarus received bad, but now Lazarus is comforted and he is in anguish."}
{"connection_id": "BC-588222b3c5b87669349b", "ref": "SBLGNT:Luke.16.25", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "rich and poor fortunes reversed", "note": "Abraham recalls the rich man's good things and Lazarus's bad things in life while their conditions now reverse; rank and fortune do not settle final worth."}
{"connection_id": "BC-1eb04112727add509f56", "ref": "SBLGNT:Luke.18.14", "target": "sec14", "tradition": "incil", "kind": "motif", "basis": "tax collector justified over Pharisee", "note": "In the paired prayer scene, Jesus says the tax collector goes home justified rather than the Pharisee; the religiously prestigious figure does not outrank the despised man who humbles himself before God."}
